+      {
+        FT_TRACE4(( "    Pushing bottom contour %ld units down\n",
+                    adjustment_amount ));
+
+        af_move_contour_vertically( hints->contours[lowest_contour],
+                                    -adjustment_amount );
+      }
+    }
